Read the cached table, identify offsetting rows with the same reference and narrative by matching C to D (and D to C), then rewrite the sheet without those rows. Compute Net Balance as Debit - Credit and convert date-like text to real datetimes. Clear the unused bottom rows in the answer region.

```python
import shutil
import openpyxl
from datetime import datetime, date

shutil.copy(INIT, OUT)

SHEET = "Imported Data"
vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb[SHEET] if SHEET in wb.sheetnames else wb.create_sheet(SHEET)
vws = vals[SHEET] if SHEET in vals.sheetnames else None
max_row = vws.max_row if vws is not None else 0


def norm_ref(v):
    if v is None:
        return ""
    if isinstance(v, bool):
        return str(v)
    if isinstance(v, (int, float)):
        if isinstance(v, float) and v.is_integer():
            return str(int(v))
        return str(v)
    return str(v).strip()


def norm_text(v):
    if v is None:
        return ""
    return str(v).strip()


def to_num(v):
    if v is None or isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        return float(v)
    if isinstance(v, str):
        s = v.strip().replace(",", "")
        if not s:
            return None
        try:
            return float(s)
        except ValueError:
            return None
    return None


def match_num(v):
    n = to_num(v)
    return 0.0 if n is None else n


def close(a, b):
    return abs(a - b) <= 1e-6


def clean_date(v):
    if isinstance(v, datetime):
        return v
    if isinstance(v, date):
        return datetime(v.year, v.month, v.day)
    if isinstance(v, str):
        s = v.strip()
        for fmt in (
            "%d/%m/%Y",
            "%Y-%m-%d",
            "%Y-%m-%d %H:%M:%S",
            "%d/%m/%Y %H:%M:%S",
            "%d-%m-%Y",
            "%m/%d/%Y",
            "%Y/%m/%d",
        ):
            try:
                return datetime.strptime(s, fmt)
            except ValueError:
                pass
        return s
    return v


def clean_value(v, col):
    if v is None:
        return None
    if col == "B":
        return clean_date(v)
    if col in ("C", "D"):
        n = to_num(v)
        if n is not None:
            return int(n) if n.is_integer() else n
        if isinstance(v, str):
            s = v.strip()
            return s if s else None
        return v
    if col in ("A", "F"):
        if isinstance(v, bool):
            return v
        if isinstance(v, (int, float)):
            if isinstance(v, float) and v.is_integer():
                return int(v)
            return v
        if isinstance(v, str):
            s = v.strip()
            return s if s else None
        return v
    if isinstance(v, str):
        s = v.strip()
        return s if s else None
    return v


rows = []
if vws is not None:
    for r in range(1, max_row + 1):
        row = {}
        for col in "ABCDEF":
            row[col] = vws[f"{col}{r}"].value
        rows.append(row)

deleted = set()
for i in range(1, len(rows)):
    if i in deleted:
        continue
    for j in range(i + 1, len(rows)):
        if j in deleted:
            continue

        ri, rj = rows[i], rows[j]

        if norm_ref(ri["A"]) != norm_ref(rj["A"]):
            continue
        if norm_text(ri["F"]) != norm_text(rj["F"]):
            continue

        ci, di = match_num(ri["C"]), match_num(ri["D"])
        cj, dj = match_num(rj["C"]), match_num(rj["D"])

        # Avoid deleting only zero/zero rows.
        if abs(ci) < 1e-9 and abs(cj) < 1e-9:
            continue

        if close(ci, dj) and close(cj, di):
            deleted.add(i)
            deleted.add(j)
            break

remaining = []
if rows:
    remaining.append(rows[0])
    remaining.extend(rows[i] for i in range(1, len(rows)) if i not in deleted)

header_row = False
if rows:
    a1 = norm_text(rows[0].get("A")).lower()
    c1 = norm_text(rows[0].get("C")).lower()
    e1 = norm_text(rows[0].get("E")).lower()
    header_row = (a1 == "reference" or c1 == "debit" or e1 == "net balance")

clear_max = max(10, len(remaining), max_row)
for r in range(1, clear_max + 1):
    for col in "ABCDEF":
        ws[f"{col}{r}"] = None

for idx, row in enumerate(remaining, start=1):
    for col in "ABCDEF":
        if col == "E" and not (idx == 1 and header_row):
            c = to_num(row.get("C"))
            d = to_num(row.get("D"))
            c = 0.0 if c is None else c
            d = 0.0 if d is None else d
            e = c - d
            val = int(e) if e.is_integer() else e
        else:
            val = clean_value(row.get(col), col)
        ws[f"{col}{idx}"] = val

print("deleted excel rows:", [i + 1 for i in sorted(deleted)])
print("remaining rows:", len(remaining))
if len(remaining) > 1:
    print("first data row:", [remaining[1].get(c) for c in "ABCDEF"])

wb.save(OUT)
